-- «نشاطك كما نفهمه» لموقع الإنجاز السريع، من كلام محمود (15 نوفمبر). يتطبق بعد 0022، ومحمود يعدّله من صفحة «الكلمات المفتاحية».
-- النشاط: استخراج تصريح الزواج. لازم طرف سعودي وطرف أجنبي (ماينفعش اتنين أجانب ولا اتنين سعوديين).
-- مش خدمتنا: خطّابة · مكتب زواج · إنشاء عقد زواج · استعلام عن معاملة · تجنيس · اللي عايز يقدّم بنفسه.
-- «شروط · طريقة · خطوات» مش هنا: بنراقبها ونحكم بالعملاء الحقيقيين (المنهجية بند 2).
-- نوع المطابقة مش هنا: المحرك بيختاره وبيفحص التعارض («عقد زواج» بتتضيّق لوحدها لو كانت هتمنع كلمة شغالة).
insert into site_brief (client_id, about, offer, exclude, fears)
select id,
  'نستخرج تصريح الزواج (موافقة وزارة الداخلية). لا بد من طرف سعودي وطرف أجنبي تنطبق عليهما الشروط. الدفع بعد الإنجاز.',
  array['تصريح زواج', 'تصاريح زواج', 'تصريح الزواج', 'موافقة زواج', 'موافقة الزواج', 'معقب', 'مكتب تصاريح'],
  '[{"word":"خطابة","why":"لسنا خطّابة"},{"word":"مكتب زواج","why":"لسنا مكتب زواج"},{"word":"مواقع زواج","why":"لسنا وسيط زواج"},{"word":"منصة زواج","why":"لسنا وسيط زواج"},{"word":"جمعية","why":"لسنا وسيط زواج"},{"word":"مسيار","why":"لسنا وسيط زواج"},{"word":"إنشاء عقد زواج","why":"لا ننشئ عقود الزواج"},{"word":"مأذون","why":"لا ننشئ عقود الزواج"},{"word":"تجنيس","why":"لا نقدم خدمات التجنيس"},{"word":"أبشر","why":"يريد التقديم بنفسه"},{"word":"سعودي من سعودية","why":"لا بد من طرف أجنبي"},{"word":"اجنبي من اجنبية","why":"لا بد من طرف سعودي"},{"word":"مقيم من مقيمة","why":"لا بد من طرف سعودي"}]'::jsonb,
  '[{"fear":"النصب","promise":"الدفع بعد الإنجاز"}]'::jsonb
from clients where name like '%نجاز%'
on conflict (client_id) do update set about = excluded.about, offer = excluded.offer, exclude = excluded.exclude, fears = excluded.fears, updated_at = now();
